    int64_t batch_idx = idx / (feature_size * normalized_elements);
    int64_t remaining = idx % (feature_size * normalized_elements);
    int64_t feature_idx = remaining / normalized_elements;
    int64_t norm_idx = remaining % normalized_elements;

    // Get precomputed mean and reciprocal std for this batch
    float cur_mean = mean[batch_idx];
    float cur_rstd = rstd[batch_idx];

    // Normalize and apply scale/shift
    float val = __half2float(input[idx]);
    float normalized = (val - cur_mean) * cur_rstd;
    float result = normalized * __half2float(weight[feature_idx]) + __half2float(bias[feature_idx]);

    output[idx] = __float2half(result);
}

// Helper function to compute mean and rstd
__global__ void compute_stats_kernel(
    const half* __restrict__ input,
    float* __restrict__ mean,
    float* __restrict__ rstd,
    int64_t total_elements,
    int64_t normalized_elements,
    int64_t batch_size,
    int64_t feature_size
) {
    extern __shared__ float shared_mem[];

    int64_t batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    float* shared_mean = shared_mem;
    float* shared_var = shared_mem + blockDim.x;

    int64_t start_idx = batch_idx * feature_size * normalized_elements;
    int64_t end_idx = start_idx + feature_size * normalized_elements;

    // Initialize shared memory
    for (int i = threadIdx.x; i < blockDim.x; i += blockDim.x) {
        shared_mean[i] = 0.0f;
        shared_var[i] = 0.0f;
    }
    __syncthreads();

    // Compute mean
    float sum = 0.0f;
    for (int64_t i = start_idx + threadIdx.x; i < end_idx; i += blockDim.x) {
        sum += __half2float(input[i]);
    }
    shared_mean[threadIdx.x] = sum;
    __syncthreads();

    // Reduce to get batch mean
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_mean[threadIdx.x] += shared_mean[threadIdx.x + stride];
        }
        __syncthreads();
    }

    float batch_mean = shared_mean[0] / (feature_size * normalized_elements);
    mean[batch_idx] = batch_mean;

    // Compute variance
    float sum_sq_diff = 0.0f;
    for (int64_t i = start_idx + threadIdx.x; i < end_idx; i += blockDim.x) {
        float diff = __half2float(input[i]) - batch_mean;
        sum_sq_diff += diff * diff;
    }
    shared_var[threadIdx.x] = sum_sq_diff;
    __syncthreads();

    // Reduce to get batch variance
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_var[threadIdx.x] += shared_var[threadIdx.x + stride];
        }
        __syncthreads();
    }

    float batch_var = shared_var[0] / (feature_size * normalized_elements);
    float batch_rstd = rsqrtf(batch_var + 1e-5f);  // Add epsilon for numerical stability
    rstd[batch_idx] = batch_rstd;
}

torch::Tensor layer_norm_forward(
    const torch::Tensor& input,
    const torch::Tensor& weight,
    const torch::Tensor& bias,
    const int64_t batch_size,
    const int64_t feature_size,
    const int64_t normalized_elements
) {
    TORCH_CHECK(input.dtype() == torch::kFloat16, "Input must be float16");
    TORCH_CHECK(weight.dtype() == torch::kFloat16, "Weight must be float16");
    TORCH_CHECK(bias.dtype() == torch::kFloat16, "Bias must be float16");
    TORCH_CHECK(input.is_cuda(), "Input must be on CUDA");
    TORCH_CHECK(weight.is_cuda(), "Weight must be on CUDA");
    TORCH_CHECK(bias.is_cuda(), "Bias must be on CUDA");

    const int64_t total_elements = input.numel();

    // Allocate output tensor
    auto output = torch::empty_like(input);

    // Compute stats
    auto mean = torch::zeros({batch_size}, torch::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA));
    auto rstd = torch::zeros({batch_size}, torch::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA));

    const int threads_per_block = 256;
    const int blocks_per_grid = (batch_size + threads_per_block - 1) / threads_per_block;

    compute_stats_kernel<<<blocks_per_grid, threads_per_block, 2 * threads_per_block * sizeof(float)>>>(
        input.data_ptr<half>(),
        mean.data_ptr<float>(),
        rstd.data_ptr<float>(),
        total_elements,
        normalized_elements,
        batch_size,
        feature_size
    );

    // Launch main kernel
    const int threads_per_block_main = 256;
    const int blocks_per_grid_main = (total_elements + threads_per_block_main - 1) / threads_per_block_main;

    layer_norm_kernel<<<blocks_per_grid_main, threads_per_block_main>>>(
        input.data_ptr<half>(),
        output.data_ptr<half>(),
        weight.data_ptr<half>(),
        bias.data_ptr<half>(),
        mean.data_ptr<float>(),
        rstd.data_ptr<float>(),
        total_elements,
        normalized_elements,
        batch_size,
        feature_size
    );

    return output;
}
